#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

int get_center(int n, const vector<vector<int>>& adj) {
    auto bfs = [&](int start, vector<int>& dist, vector<int>& parent) {
        fill(dist.begin(), dist.end(), -1);
        fill(parent.begin(), parent.end(), -1);
        queue<int> q;
        q.push(start);
        dist[start] = 0;
        int farthest = start;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            if (dist[u] > dist[farthest]) {
                farthest = u;
            }

            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.push(v);
                }
            }
        }
        return farthest;
    };

    vector<int> dist(n + 1), parent(n + 1);
    int u = bfs(1, dist, parent);
    int v = bfs(u, dist, parent);

    vector<int> path;
    int curr = v;
    while (curr != -1) {
        path.push_back(curr);
        curr = parent[curr];
    }

    return path[path.size() / 2];
}

